PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE vendedores (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nome TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL,
  senha_hash TEXT NOT NULL,
  role TEXT DEFAULT 'vendedor',
  status TEXT DEFAULT 'ativo',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE clientes (   id INTEGER PRIMARY KEY AUTOINCREMENT,   vendedor_id INTEGER,   tipo_pessoa TEXT DEFAULT 'PJ',   documento TEXT UNIQUE NOT NULL,   cnpj TEXT,   cpf TEXT,   razao_social TEXT,   nome_estabelecimento TEXT,   nome_fantasia TEXT,   ie TEXT,   situacao_ie TEXT DEFAULT 'pendente',   responsavel_empresa TEXT,   responsavel_compra TEXT,   telefone TEXT,   whatsapp TEXT,   instagram TEXT,   email TEXT,   contato_emergencia TEXT,   cep TEXT,   endereco TEXT,   cidade TEXT,   estado TEXT,   concorrentes TEXT,   observacoes_gerais TEXT,   status_comercial TEXT DEFAULT 'prospect',   status_cliente TEXT DEFAULT 'ativo',   ultima_visita TEXT,   created_at DATETIME DEFAULT CURRENT_TIMESTAMP,   updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE produtos (     id INTEGER PRIMARY KEY AUTOINCREMENT,     nome TEXT NOT NULL,     unidade TEXT DEFAULT 'Fardo',     preco REAL DEFAULT 0,     ativo TEXT DEFAULT 'ativo' );
CREATE TABLE visitas (     id INTEGER PRIMARY KEY AUTOINCREMENT,     vendedor_id INTEGER NOT NULL,     cliente_id INTEGER NOT NULL,     data_visita TEXT NOT NULL,     comprou TEXT DEFAULT 'nao',     valor_total REAL DEFAULT 0,     observacoes TEXT,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE visita_itens (     id INTEGER PRIMARY KEY AUTOINCREMENT,     visita_id INTEGER NOT NULL,     produto_id INTEGER,     produto_nome TEXT NOT NULL,     quantidade REAL DEFAULT 0,     preco_unitario REAL DEFAULT 0,     subtotal REAL DEFAULT 0 );
CREATE TABLE clientes_avulsos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  vendedor_id INTEGER NOT NULL,
  nome_estabelecimento TEXT NOT NULL,
  tipo_pessoa TEXT,
  cpf TEXT,
  cnpj TEXT,
  telefone TEXT,
  whatsapp TEXT,
  cep TEXT,
  endereco TEXT,
  cidade TEXT,
  estado TEXT,
  observacoes_gerais TEXT,
  status_cadastro TEXT NOT NULL DEFAULT 'incompleto',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_vendedores_email ON vendedores(email);
CREATE INDEX idx_vendedores_status ON vendedores(status);
CREATE INDEX idx_vendedores_role ON vendedores(role);
CREATE INDEX idx_clientes_avulsos_vendedor
  ON clientes_avulsos(vendedor_id);
CREATE INDEX idx_clientes_avulsos_nome
  ON clientes_avulsos(nome_estabelecimento);
CREATE INDEX idx_clientes_avulsos_status
  ON clientes_avulsos(status_cadastro);
